//! Raw FFI bindings to libllama (and the parts of ggml its header exposes).
//!
//! `bindings.rs` is generated by `scripts/gen-bindings.ps1` from the vendored
//! `vendor/llama.cpp/include/llama.h`. Everything here is `unsafe`; use the
//! `dfin-llama` crate for a safe API.

#![allow(non_upper_case_globals, non_camel_case_types, non_snake_case, dead_code)]
#![allow(clippy::all)]

include!("bindings.rs");

/// Whether the vendored libllama carries the layer-range patch.
pub const HAS_LAYER_RANGE: bool = cfg!(has_layer_range);

/// Set the `[layer_begin, layer_end)` range on model parameters. Returns `false`
/// (and leaves the params untouched) when the vendored tree lacks the patch.
pub fn set_layer_range(params: &mut llama_model_params, begin: i32, end: i32) -> bool {
    #[cfg(has_layer_range)]
    {
        params.layer_begin = begin;
        params.layer_end = end;
        true
    }
    #[cfg(not(has_layer_range))]
    {
        let _ = (params, begin, end);
        false
    }
}

/// The resolved layer range of a loaded model, if the patch is present.
///
/// # Safety
/// `model` must be a valid, loaded `llama_model`.
pub unsafe fn model_layer_range(model: *const llama_model) -> Option<(i32, i32)> {
    #[cfg(has_layer_range)]
    {
        Some((llama_model_layer_begin(model), llama_model_layer_end(model)))
    }
    #[cfg(not(has_layer_range))]
    {
        let _ = model;
        None
    }
}
